from __future__ import annotations


INDEX_HTML = r"""
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="theme-color" content="#080a0f">
  <link rel="icon" type="image/png" href="assets/mediahub-icon.png">
  <title>MediaHub</title>
  <style>
    :root {
      color-scheme: dark; font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      --bg:#080a0f; --surface:#121620; --surface-2:#1a202d; --border:rgba(255,255,255,.1);
      --text:#f7f8fb; --muted:#9ba6b7; --accent:#7c5cff; --accent-2:#4e8dff;
      --success:#3ad68c; --warning:#ffc65a; --danger:#ff7389;
    }
    *{box-sizing:border-box} body{margin:0;background:var(--bg);color:var(--text);min-height:100vh} button,input,select{font:inherit}
    button{cursor:pointer}.hidden{display:none!important}.muted{color:var(--muted)}
    .topbar{position:sticky;top:0;z-index:20;height:68px;padding:0 clamp(16px,4vw,54px);display:flex;align-items:center;gap:26px;background:rgba(8,10,15,.88);backdrop-filter:blur(18px);border-bottom:1px solid var(--border)}
    .brand{display:flex;align-items:center;flex:0 0 auto}.brand img{display:block;width:154px;height:auto}
    nav{display:flex;gap:4px}nav button{border:0;background:transparent;color:var(--muted);padding:9px 13px;border-radius:10px;font-weight:750}nav button.active,nav button:hover{color:var(--text);background:rgba(255,255,255,.07)}
    .user{margin-left:auto;color:var(--muted);font-size:.84rem}.shell{max-width:1500px;margin:auto;padding:28px clamp(16px,4vw,54px) 70px}
    .hero{min-height:270px;border-radius:26px;padding:clamp(26px,5vw,62px);display:flex;align-items:end;position:relative;overflow:hidden;background:radial-gradient(circle at 80% 20%,rgba(124,92,255,.3),transparent 34rem),linear-gradient(135deg,#151b2b,#0d1018);border:1px solid var(--border)}
    .hero:after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(5,7,11,.3),transparent)}.hero-copy{position:relative;z-index:1;max-width:720px}.eyebrow{color:#ae9cff;text-transform:uppercase;letter-spacing:.14em;font-size:.74rem;font-weight:900}
    h1{font-size:clamp(2.3rem,6vw,5rem);line-height:.95;letter-spacing:-.055em;margin:10px 0 16px}.hero p{color:#c1c8d4;line-height:1.6;margin:0;max-width:620px}
    .searchbar{display:flex;gap:10px;margin:24px 0}.searchbar input,.field input,.field select{width:100%;border:1px solid var(--border);background:#0d1119;color:var(--text);border-radius:12px;padding:12px 14px;outline:none}.searchbar input:focus,.field input:focus,.field select:focus{border-color:var(--accent)}
    .button{border:1px solid var(--border);background:var(--surface-2);color:var(--text);border-radius:12px;padding:11px 16px;font-weight:800}.button:hover{filter:brightness(1.12)}.button.primary{border:0;background:linear-gradient(135deg,var(--accent-2),var(--accent))}.button.danger{background:rgba(255,115,137,.13);color:var(--danger)}.button:disabled{opacity:.5;cursor:wait}
    .filters{display:flex;gap:8px;overflow:auto;margin-bottom:24px}.chip{border:1px solid var(--border);background:transparent;color:var(--muted);border-radius:999px;padding:8px 13px;white-space:nowrap}.chip.active{background:#252b3a;color:white;border-color:#3c455a}
    .discovery-tools{display:grid;grid-template-columns:minmax(180px,1.4fr) repeat(4,minmax(115px,1fr)) auto;gap:10px;align-items:end;margin:0 0 24px;padding:16px;border:1px solid var(--border);border-radius:16px;background:rgba(18,22,32,.62)}.discovery-tools .field select,.discovery-tools .field input{min-height:44px}.load-more{display:flex;justify-content:center;margin:28px 0 8px}.load-more .button{min-width:180px}
    .heading{display:flex;align-items:end;justify-content:space-between;gap:16px;margin:28px 0 16px}.heading h2{margin:0;font-size:1.5rem;letter-spacing:-.03em}.heading p{margin:5px 0 0;color:var(--muted)}
    .movies{display:grid;grid-template-columns:repeat(auto-fill,minmax(155px,1fr));gap:20px}.movie{border:0;background:transparent;color:inherit;padding:0;text-align:left;min-width:0}.poster{aspect-ratio:2/3;border-radius:15px;overflow:hidden;background:linear-gradient(145deg,#20283a,#10141e);border:1px solid var(--border);box-shadow:0 15px 35px rgba(0,0,0,.28);transition:transform .18s ease,box-shadow .18s ease}.movie:hover .poster{transform:translateY(-4px) scale(1.01);box-shadow:0 22px 48px rgba(0,0,0,.4)}.poster img{width:100%;height:100%;object-fit:cover}.no-poster{height:100%;display:grid;place-items:center;color:var(--muted);padding:20px;text-align:center;font-weight:800}.movie-title{font-weight:800;margin-top:10px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.movie-meta{color:var(--muted);font-size:.8rem;margin-top:4px}
    .empty{padding:52px 20px;text-align:center;color:var(--muted);border:1px dashed var(--border);border-radius:18px}.panel{background:var(--surface);border:1px solid var(--border);border-radius:20px;padding:20px}.downloads{display:grid;gap:12px}.download{display:grid;grid-template-columns:1fr auto;gap:12px;align-items:center}.download h3{margin:0 0 6px;font-size:1rem}.progress{height:7px;background:#080b11;border-radius:99px;overflow:hidden;margin-top:10px}.progress span{display:block;height:100%;background:linear-gradient(90deg,var(--accent-2),var(--accent));border-radius:inherit}.status{font-size:.72rem;font-weight:900;padding:5px 9px;border-radius:99px;background:rgba(78,141,255,.12);color:#85afff}.status.available{color:var(--success);background:rgba(58,214,140,.12)}.status.failed,.status.rejected{color:var(--danger);background:rgba(255,115,137,.12)}
    .setup-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.service{background:var(--surface);border:1px solid var(--border);border-radius:18px;padding:18px}.service-head{display:flex;justify-content:space-between;gap:10px;margin-bottom:14px;font-weight:900}.fields{display:grid;gap:11px}.field{display:grid;gap:6px;color:#c8d0dd;font-size:.78rem;font-weight:750}.hint{font-size:.75rem;color:var(--muted);line-height:1.45}.badge{font-size:.7rem;padding:5px 8px;border-radius:99px;color:var(--muted);background:#252b38}.badge.connected,.badge.healthy{color:var(--success);background:rgba(58,214,140,.12)}.badge.warning{color:var(--warning);background:rgba(255,198,90,.12)}.badge.error{color:var(--danger);background:rgba(255,115,137,.12)}.workflow-card{grid-column:1/-1}.workflow-checks{display:grid;gap:8px}.workflow-check{padding:10px 12px;border-radius:11px;background:#0d1119;color:var(--muted);font-size:.78rem;line-height:1.45}.workflow-check.ok{color:#a9ecca}.workflow-check.warning{color:var(--warning)}.workflow-check.error{color:var(--danger)}.setup-actions{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-top:18px}.message{color:var(--muted);font-size:.86rem}.message.error{color:var(--danger)}.message.success{color:var(--success)}
    .modal{position:fixed;inset:0;z-index:50;background:rgba(0,0,0,.72);display:grid;place-items:center;padding:18px}.dialog{position:relative;width:min(960px,100%);max-height:92vh;overflow:auto;background:#111620;border:1px solid var(--border);border-radius:24px;box-shadow:0 30px 90px rgba(0,0,0,.65)}.close{position:absolute;right:14px;top:14px;z-index:3;width:38px;height:38px;border:1px solid var(--border);border-radius:50%;background:rgba(8,10,15,.75);color:white}.detail-hero{min-height:340px;padding:34px;display:flex;align-items:end;background-size:cover;background-position:center;position:relative}.detail-hero:before{content:"";position:absolute;inset:0;background:linear-gradient(0deg,#111620 2%,rgba(17,22,32,.32) 70%),linear-gradient(90deg,rgba(17,22,32,.88),transparent)}.detail-copy{position:relative;max-width:670px}.detail-copy h2{font-size:clamp(2rem,6vw,4rem);line-height:1;margin:8px 0 14px;letter-spacing:-.04em}.detail-body{padding:0 34px 34px}.actions{display:flex;flex-wrap:wrap;gap:10px;margin:18px 0}.release-rules{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:18px 0}.releases{display:grid;gap:10px}.release{display:grid;grid-template-columns:1fr auto;gap:14px;padding:14px;border:1px solid var(--border);border-radius:14px;background:#0c1018}.release h4{margin:0 0 7px;overflow-wrap:anywhere}.release-meta{color:var(--muted);font-size:.8rem;display:flex;gap:10px;flex-wrap:wrap}.release-reasons{color:var(--danger);font-size:.77rem;margin-top:8px}.toast{position:fixed;right:20px;bottom:20px;z-index:80;max-width:390px;padding:14px 17px;border-radius:14px;background:#202738;border:1px solid var(--border);box-shadow:0 20px 55px rgba(0,0,0,.45)}
    .attribution{margin-top:32px;color:#697487;font-size:.72rem;text-align:center}
    .auth-screen{position:fixed;inset:0;z-index:100;display:grid;place-items:center;padding:20px;background:radial-gradient(circle at 50% 15%,rgba(124,92,255,.2),transparent 36rem),var(--bg)}.login-card{width:min(440px,100%);padding:34px;border:1px solid var(--border);border-radius:24px;background:rgba(18,22,32,.96);box-shadow:0 32px 90px rgba(0,0,0,.55)}.login-brand{display:flex;align-items:center}.login-brand img{display:block;width:min(310px,100%);height:auto}.login-card h1{font-size:2.15rem;margin:28px 0 10px}.login-card p{color:var(--muted);line-height:1.55}.login-card form{display:grid;gap:14px;margin-top:24px}.login-card .button{margin-top:4px}.login-message{min-height:21px;color:var(--danger);font-size:.84rem}
    .user-layout{display:grid;grid-template-columns:minmax(290px,390px) 1fr;gap:18px;align-items:start}.user-list{display:grid;gap:10px}.user-card{display:grid;grid-template-columns:1fr auto;gap:16px;align-items:center}.user-card h3{margin:0 0 5px}.user-meta{font-size:.78rem;color:var(--muted)}.user-controls{display:flex;flex-wrap:wrap;justify-content:end;gap:8px}.user-controls select{border:1px solid var(--border);background:#0d1119;color:var(--text);border-radius:10px;padding:9px}.account-source{display:inline-block;margin-left:7px;padding:3px 7px;border-radius:999px;background:#252b38;color:#bcc5d3;font-size:.65rem;font-weight:800}.form-title{margin:0 0 16px}.stack{display:grid;gap:12px}
    @media(max-width:900px){.user-layout{grid-template-columns:1fr}.user-controls{justify-content:start}}
    @media(max-width:760px){.topbar{gap:10px;height:auto;min-height:62px;flex-wrap:wrap;padding-block:10px}.brand img{width:142px}.user{display:none}.shell{padding-top:18px}.hero{min-height:230px}.setup-grid{grid-template-columns:1fr}.discovery-tools{grid-template-columns:1fr 1fr}.discovery-tools .genre-field{grid-column:1/-1}.discovery-tools .clear-filters{grid-column:1/-1}.movies{grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.release-rules{grid-template-columns:1fr}.detail-hero{min-height:290px;padding:24px}.detail-body{padding:0 20px 24px}.setup-actions{align-items:stretch;flex-direction:column}.setup-actions .button{width:100%}.user-card{grid-template-columns:1fr}.login-card{padding:26px}}
  </style>
</head>
<body>
  <header class="topbar">
    <div class="brand"><img src="assets/mediahub-logo.png" alt="MediaHub by Stu"></div>
    <nav aria-label="Main navigation">
      <button class="active" data-view="browse">Browse</button>
      <button data-view="downloads">Downloads</button>
      <button data-view="setup" id="setup-nav">Setup</button>
      <button data-view="users" id="users-nav">Users</button>
      <button id="logout" class="hidden">Sign out</button>
    </nav>
    <div class="user" id="user">Connecting...</div>
  </header>

  <main class="shell">
    <section id="browse-view">
      <div class="hero"><div class="hero-copy"><div class="eyebrow">Your private media catalogue</div><h1>Find something worth watching.</h1><p>Browse movie metadata from TMDb, then request an approved IPTorrents release through Radarr and Prowlarr.</p></div></div>
      <form class="searchbar" id="search-form"><input id="search" type="search" maxlength="200" placeholder="Search movies, actors or titles" aria-label="Search movies"><button class="button primary">Search</button></form>
      <div class="filters" id="filters">
        <button class="chip active" data-collection="popular">Popular</button><button class="chip" data-collection="now_playing">Now playing</button><button class="chip" data-collection="top_rated">Top rated</button><button class="chip" data-collection="upcoming">Upcoming</button>
      </div>
      <div class="discovery-tools" aria-label="Movie filters">
        <label class="field genre-field">Genre<select id="genre-filter"><option value="">All genres</option></select></label>
        <label class="field">Released from<input id="year-from" type="number" min="1874" max="2100" inputmode="numeric" placeholder="Any year"></label>
        <label class="field">Released to<input id="year-to" type="number" min="1874" max="2100" inputmode="numeric" placeholder="Any year"></label>
        <label class="field">Rating from<input id="rating-from" type="number" min="1" max="10" step="0.1" inputmode="decimal" placeholder="1.0"></label>
        <label class="field">Rating to<input id="rating-to" type="number" min="1" max="10" step="0.1" inputmode="decimal" placeholder="10.0"></label>
        <button class="button clear-filters" id="clear-filters" type="button">Clear filters</button>
      </div>
      <div class="heading"><div><h2 id="catalogue-title">Popular movies</h2><p id="catalogue-meta">Loading TMDb...</p></div></div>
      <div class="movies" id="movies"></div>
      <div class="load-more hidden" id="load-more-area"><button class="button" id="load-more" type="button">Load more movies</button></div>
      <p class="attribution">This product uses the TMDB API but is not endorsed or certified by TMDB.</p>
    </section>

    <section id="downloads-view" class="hidden">
      <div class="heading"><div><h2>Requests and downloads</h2><p>Live status from Radarr and qBittorrent.</p></div><button class="button" id="refresh-downloads">Refresh</button></div>
      <div class="downloads" id="downloads"></div>
    </section>

    <section id="setup-view" class="hidden">
      <div class="heading"><div><h2>Service connections</h2><p>Credentials remain private inside MediaHub. IPTorrents authentication stays in Prowlarr.</p></div><button class="button" id="discover">Discover again</button></div>
      <form id="setup-form"><div class="setup-grid">
        <article class="service" data-service="tmdb"><div class="service-head"><span>TMDb</span><span class="badge" data-status>Checking</span></div><div class="fields"><label class="field">API key<input id="tmdb_api_key" type="password" autocomplete="new-password" placeholder="TMDb API key"></label><div class="hint">Posters, metadata, discovery and search.</div></div></article>
        <article class="service" data-service="prowlarr"><div class="service-head"><span>Prowlarr</span><span class="badge" data-status>Checking</span></div><div class="fields"><label class="field">URL<input id="prowlarr_url" type="url"></label><label class="field">API key<input id="prowlarr_api_key" type="password" autocomplete="new-password"></label><div class="hint">Authenticated IPTorrents searches are performed by Prowlarr.</div></div></article>
        <article class="service" data-service="radarr"><div class="service-head"><span>Radarr</span><span class="badge" data-status>Checking</span></div><div class="fields"><label class="field">URL<input id="radarr_url" type="url"></label><label class="field">API key<input id="radarr_api_key" type="password" autocomplete="new-password"></label><label class="field">Movie root folder<select id="radarr_root_folder_path"><option value="">Automatic</option></select></label><label class="field">Quality profile<select id="radarr_quality_profile_id"><option value="0">Automatic</option></select></label><div class="hint">Adds movies, performs interactive searches and grabs approved releases.</div></div></article>
        <article class="service" data-service="sonarr"><div class="service-head"><span>Sonarr</span><span class="badge" data-status>Checking</span></div><div class="fields"><label class="field">URL<input id="sonarr_url" type="url"></label><label class="field">API key<input id="sonarr_api_key" type="password" autocomplete="new-password"></label><div class="hint">Television support follows in the next workflow slice.</div></div></article>
        <article class="service" data-service="qbittorrent"><div class="service-head"><span>qBittorrent</span><span class="badge" data-status>Checking</span></div><div class="fields"><label class="field">URL<input id="qbittorrent_url" type="url"></label><label class="field">Authentication<select id="qbittorrent_auth_method"><option value="password">Username and password</option><option value="api_key">API key (qBittorrent 5.2+)</option></select></label><label class="field">API key<input id="qbittorrent_api_key" type="password" autocomplete="new-password" placeholder="Optional qbt_ API key"></label><label class="field">Username<input id="qbittorrent_username" autocomplete="username"></label><label class="field">Password<input id="qbittorrent_password" type="password" autocomplete="new-password"></label><div class="hint">Choose one authentication method. API keys require qBittorrent 5.2 or newer. Radarr remains responsible for submitting downloads.</div></div></article>
        <article class="service workflow-card"><div class="service-head"><span>Download workflow</span><span class="badge" id="workflow-status">Checking</span></div><div class="workflow-checks" id="workflow-checks"><div class="hint">Checking Radarr hardlinks and download paths...</div></div></article>
      </div><div class="setup-actions"><div class="message" id="setup-message">Loading setup...</div><button class="button primary" id="save-setup">Save and test</button></div></form>
    </section>

    <section id="users-view" class="hidden">
      <div class="heading"><div><h2>MediaHub users</h2><p>Create accounts for people who need access without signing into Home Assistant.</p></div><button class="button" id="refresh-users">Refresh</button></div>
      <div class="user-layout">
        <form class="panel stack" id="create-user-form">
          <h3 class="form-title">Create MediaHub account</h3>
          <label class="field">Display name<input id="new-display-name" maxlength="250" required placeholder="Lee"></label>
          <label class="field">Username<input id="new-username" minlength="3" maxlength="100" autocomplete="off" required placeholder="lee"></label>
          <label class="field">Temporary password<input id="new-password" type="password" minlength="12" maxlength="1024" autocomplete="new-password" required></label>
          <label class="field">Role<select id="new-role"><option value="requester">Requester</option><option value="manager">Manager</option><option value="admin">Administrator</option></select></label>
          <div class="hint">The password is stored as a one-way hash. Give it to the user privately, then reset it here whenever required.</div>
          <div class="message" id="user-message"></div>
          <button class="button primary">Create account</button>
        </form>
        <div class="user-list" id="user-list"><div class="empty">Loading users...</div></div>
      </div>
    </section>
  </main>

  <div class="auth-screen hidden" id="login-screen">
    <div class="login-card">
      <div class="login-brand"><img src="assets/mediahub-logo.png" alt="MediaHub by Stu"></div>
      <h1>Welcome back.</h1>
      <p>Sign in to search, request and track movies. This account is separate from Home Assistant.</p>
      <form id="login-form">
        <label class="field">Username<input id="login-username" autocomplete="username" maxlength="100" required autofocus></label>
        <label class="field">Password<input id="login-password" type="password" autocomplete="current-password" maxlength="1024" required></label>
        <div class="login-message" id="login-message"></div>
        <button class="button primary" id="login-button">Sign in</button>
      </form>
    </div>
  </div>

  <div class="modal hidden" id="modal" role="dialog" aria-modal="true" aria-labelledby="detail-title"><div class="dialog"><button class="close" id="close-modal" aria-label="Close">✕</button><div id="detail"></div></div></div>
  <div class="toast hidden" id="toast" role="status"></div>

  <script>
    const state={user:null,collection:'popular',query:'',genreId:'',yearFrom:'',yearTo:'',ratingFrom:'',ratingTo:'',page:1,totalPages:1,movie:null,view:'browse',movieLoading:false,movieReload:false,downloadTimer:null,downloadLoading:false};
    const secretFields=['tmdb_api_key','prowlarr_api_key','radarr_api_key','sonarr_api_key','qbittorrent_api_key','qbittorrent_password'];
    const serviceNames=['tmdb','prowlarr','radarr','sonarr','qbittorrent'];
    const esc=value=>String(value??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
    const endpoint=path=>`api/${path}`;
    async function api(path,options={}){const requestOptions={...options};const headers=new Headers(options.headers||{});const method=(requestOptions.method||'GET').toUpperCase();if(state.user?.csrf_token&&!['GET','HEAD','OPTIONS'].includes(method))headers.set('X-CSRF-Token',state.user.csrf_token);requestOptions.headers=headers;const response=await fetch(endpoint(path),requestOptions);const body=await response.json().catch(()=>({}));if(!response.ok){const detail=body.detail;const error=new Error(typeof detail==='string'?detail:detail?.message||'Request failed');error.status=response.status;if(response.status===401&&state.user?.auth_source==='mediahub')showLogin('Your session expired. Sign in again.');throw error;}return body;}
    function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.remove('hidden');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.add('hidden'),5000);}
    function showView(name){state.view=name;clearInterval(state.downloadTimer);state.downloadTimer=null;document.querySelectorAll('nav button[data-view]').forEach(button=>button.classList.toggle('active',button.dataset.view===name));['browse','downloads','setup','users'].forEach(view=>document.getElementById(`${view}-view`).classList.toggle('hidden',view!==name));if(name==='downloads'){loadDownloads();state.downloadTimer=setInterval(()=>{if(state.view==='downloads')loadDownloads(true);},10000);}if(name==='setup')loadSetup();if(name==='users')loadUsers();}
    document.querySelectorAll('nav button[data-view]').forEach(button=>button.addEventListener('click',()=>showView(button.dataset.view)));

    function poster(movie){return movie.poster_url?`<img loading="lazy" src="${esc(movie.poster_url)}" alt="${esc(movie.title)} poster">`:`<div class="no-poster">${esc(movie.title)}</div>`;}
    function movieCard(movie){return`<button class="movie" data-id="${movie.tmdb_id}"><div class="poster">${poster(movie)}</div><div class="movie-title">${esc(movie.title)}</div><div class="movie-meta">${esc(movie.year||'Year unknown')} · ★ ${movie.rating.toFixed(1)}</div></button>`;}
    function bindMovieCards(container){container.querySelectorAll('.movie:not([data-bound])').forEach(card=>{card.dataset.bound='true';card.addEventListener('click',()=>openMovie(card.dataset.id));});}
    async function loadMovies(append=false){if(state.movieLoading){if(!append)state.movieReload=true;return;}state.movieLoading=true;const container=document.getElementById('movies');const loadMore=document.getElementById('load-more');if(!append){state.page=1;container.innerHTML='<div class="empty">Loading movies...</div>';}else{loadMore.disabled=true;loadMore.textContent='Loading...';}const params=new URLSearchParams({page:String(state.page),collection:state.collection});if(state.query)params.set('query',state.query);if(state.genreId)params.set('genre_id',state.genreId);if(state.yearFrom)params.set('year_from',state.yearFrom);if(state.yearTo)params.set('year_to',state.yearTo);if(state.ratingFrom)params.set('rating_from',state.ratingFrom);if(state.ratingTo)params.set('rating_to',state.ratingTo);try{const data=await api(`catalog/movies?${params}`);state.page=data.page;state.totalPages=data.total_pages;document.getElementById('catalogue-title').textContent=state.query?`Results for “${state.query}”`:`${state.collection.replace('_',' ')} movies`;const filterNote=data.post_filtered_search?' Filters are applied to each search page.':'';document.getElementById('catalogue-meta').textContent=`${data.total_results.toLocaleString()} titles available · page ${data.page} of ${data.total_pages}.${filterNote}`;const cards=data.movies.map(movieCard).join('');if(append){if(cards&&container.querySelector('.empty'))container.innerHTML='';container.insertAdjacentHTML('beforeend',cards);}else{container.innerHTML=cards||'<div class="empty">No movies matched those filters.</div>';}bindMovieCards(container);document.getElementById('load-more-area').classList.toggle('hidden',state.page>=state.totalPages);}catch(error){if(append){state.page=Math.max(1,state.page-1);toast(error.message);document.getElementById('load-more-area').classList.remove('hidden');}else{container.innerHTML=`<div class="empty">${esc(error.message)}. Open Setup and connect TMDb.</div>`;document.getElementById('load-more-area').classList.add('hidden');}}finally{state.movieLoading=false;loadMore.disabled=false;loadMore.textContent='Load more movies';if(state.movieReload){state.movieReload=false;loadMovies();}}}
    async function loadGenres(){try{const data=await api('catalog/genres');const select=document.getElementById('genre-filter');select.innerHTML='<option value="">All genres</option>'+data.genres.map(genre=>`<option value="${genre.id}">${esc(genre.name)}</option>`).join('');select.value=state.genreId;}catch(error){/* Movie browsing still works if the genre list is temporarily unavailable. */}}
    function applyDiscoveryFilters(){state.genreId=document.getElementById('genre-filter').value;state.yearFrom=document.getElementById('year-from').value;state.yearTo=document.getElementById('year-to').value;state.ratingFrom=document.getElementById('rating-from').value;state.ratingTo=document.getElementById('rating-to').value;if(state.yearFrom&&state.yearTo&&Number(state.yearFrom)>Number(state.yearTo)){toast('The starting release year must be before the ending year.');return;}if(state.ratingFrom&&state.ratingTo&&Number(state.ratingFrom)>Number(state.ratingTo)){toast('The minimum rating must be lower than the maximum rating.');return;}loadMovies();}
    document.getElementById('search-form').addEventListener('submit',event=>{event.preventDefault();state.query=document.getElementById('search').value.trim();loadMovies();});
    document.querySelectorAll('[data-collection]').forEach(button=>button.addEventListener('click',()=>{state.collection=button.dataset.collection;state.query='';document.getElementById('search').value='';document.querySelectorAll('[data-collection]').forEach(item=>item.classList.toggle('active',item===button));loadMovies();}));
    ['genre-filter','year-from','year-to','rating-from','rating-to'].forEach(id=>document.getElementById(id).addEventListener('change',applyDiscoveryFilters));
    document.getElementById('clear-filters').addEventListener('click',()=>{['genre-filter','year-from','year-to','rating-from','rating-to'].forEach(id=>document.getElementById(id).value='');state.genreId='';state.yearFrom='';state.yearTo='';state.ratingFrom='';state.ratingTo='';loadMovies();});
    document.getElementById('load-more').addEventListener('click',()=>{if(state.page<state.totalPages){state.page+=1;loadMovies(true);}});

    async function openMovie(id){const modal=document.getElementById('modal');modal.classList.remove('hidden');document.getElementById('detail').innerHTML='<div class="empty">Loading movie details...</div>';try{state.movie=await api(`catalog/movies/${id}`);renderDetail();}catch(error){document.getElementById('detail').innerHTML=`<div class="empty">${esc(error.message)}</div>`;}}
    function renderDetail(){const movie=state.movie;const genres=(movie.genres||[]).map(item=>item.name).join(' · ');const backdrop=movie.backdrop_url?`background-image:url('${esc(movie.backdrop_url)}')`:'';document.getElementById('detail').innerHTML=`<div class="detail-hero" style="${backdrop}"><div class="detail-copy"><div class="eyebrow">${esc(genres||'Movie')}</div><h2 id="detail-title">${esc(movie.title)}</h2><div class="muted">${esc(movie.year||'')} · ${movie.runtime_minutes?`${movie.runtime_minutes} min · `:''}★ ${movie.rating.toFixed(1)}</div><div class="actions"><button class="button primary" id="auto-request">Request best release</button><button class="button" id="choose-release">Choose a release</button>${movie.trailer_url?`<a class="button" href="${esc(movie.trailer_url)}" target="_blank" rel="noopener">Watch trailer</a>`:''}</div></div></div><div class="detail-body"><p class="muted">${esc(movie.overview||'No synopsis is available.')}</p><div id="release-area"></div></div>`;document.getElementById('auto-request').addEventListener('click',event=>submitRequest(null,event.currentTarget));document.getElementById('choose-release').addEventListener('click',findReleases);}
    function rules(){return{maximum_size_gb:Number(document.getElementById('max-size')?.value||3),minimum_seeders:Number(document.getElementById('min-seeders')?.value||1),quality_mode:document.getElementById('quality-mode')?.value||'720p_and_1080p'};}
    function rulesHtml(values={maximum_size_gb:3,minimum_seeders:1,quality_mode:'720p_and_1080p'}){const mode=values.quality_mode||'720p_and_1080p';return`<div class="release-rules"><label class="field">Maximum size (GB)<input id="max-size" type="number" min="0.1" max="100" step="0.1" value="${esc(values.maximum_size_gb??3)}"></label><label class="field">Minimum seeders<input id="min-seeders" type="number" min="0" value="${esc(values.minimum_seeders??1)}"></label><label class="field">Quality<select id="quality-mode"><option value="720p_and_1080p" ${mode==='720p_and_1080p'?'selected':''}>720p and 1080p</option><option value="1080p_only" ${mode==='1080p_only'?'selected':''}>1080p only</option><option value="720p_only" ${mode==='720p_only'?'selected':''}>720p only</option></select></label></div>`;}
    async function findReleases(){const area=document.getElementById('release-area');const selectedRules=rules();area.innerHTML=`${rulesHtml(selectedRules)}<div class="empty">Searching IPTorrents through Radarr and Prowlarr...</div>`;try{const data=await api(`movies/${state.movie.tmdb_id}/releases`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(selectedRules)});area.innerHTML=`${rulesHtml(selectedRules)}<div class="heading"><div><h2>Available releases</h2><p>${data.releases.length} results from your configured indexers.</p></div><button class="button" id="rerun-search">Search again</button></div><div class="releases">${data.releases.map(release=>`<article class="release"><div><h4>${esc(release.title)}</h4><div class="release-meta"><span>${esc(release.indexer)}</span><span>${esc(release.quality)}</span><span>${release.size_gb.toFixed(2)} GB</span><span>${release.seeders??'?'} seeders</span><span>${release.age_hours}h old</span>${release.flags.map(flag=>`<span>${esc(flag)}</span>`).join('')}</div>${release.policy_rejections.length?`<div class="release-reasons">${esc(release.policy_rejections.join(' · '))}</div>`:''}</div><button class="button ${release.eligible?'primary':''}" data-token="${esc(release.release_token)}" ${release.eligible?'':'disabled'}>${release.eligible?'Download':'Rejected'}</button></article>`).join('')||'<div class="empty">No releases were returned. Check the IPTorrents indexer in Prowlarr.</div>'}</div>`;document.getElementById('rerun-search').addEventListener('click',findReleases);area.querySelectorAll('[data-token]').forEach(button=>button.addEventListener('click',()=>submitRequest(button.dataset.token,button)));}catch(error){area.innerHTML=`${rulesHtml(selectedRules)}<div class="empty">${esc(error.message)}</div>`;}}
    async function submitRequest(token,button){button.disabled=true;const original=button.textContent;button.textContent='Requesting...';try{await api(`movies/${state.movie.tmdb_id}/request`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...rules(),release_token:token})});toast(`${state.movie.title} was sent to Radarr.`);closeModal();showView('downloads');}catch(error){toast(error.message);button.disabled=false;button.textContent=original;}}
    function closeModal(){document.getElementById('modal').classList.add('hidden');state.movie=null;}document.getElementById('close-modal').addEventListener('click',closeModal);document.getElementById('modal').addEventListener('click',event=>{if(event.target.id==='modal')closeModal();});

    async function loadDownloads(silent=false){if(state.downloadLoading)return;state.downloadLoading=true;const container=document.getElementById('downloads');if(!silent)container.innerHTML='<div class="empty">Refreshing Radarr and qBittorrent...</div>';try{const data=await api('downloads');container.innerHTML=data.length?data.map(item=>`<article class="panel download"><div><h3>${esc(item.title)}</h3><div class="muted">Requested by ${esc(item.requested_by_name)} · ${esc(item.status_message||item.status)}</div><div class="progress"><span style="width:${Number(item.progress||0)}%"></span></div></div><span class="status ${esc(item.status)}">${esc(item.status.replaceAll('_',' '))} ${Number(item.progress||0).toFixed(0)}%</span></article>`).join(''):'<div class="empty">No movie requests yet. Browse the catalogue to request one.</div>';}catch(error){if(!silent)container.innerHTML=`<div class="empty">${esc(error.message)}</div>`;}finally{state.downloadLoading=false;}}document.getElementById('refresh-downloads').addEventListener('click',()=>loadDownloads());

    function setSetupMessage(text,kind=''){const el=document.getElementById('setup-message');el.textContent=text;el.className=`message ${kind}`;}
    function statusLabel(value){return({connected:'Connected',not_configured:'Needs details',authentication_failed:'Check credentials',unavailable:'Unavailable',invalid_response:'Invalid response'})[value]||'Not configured';}
    async function loadRadarrOptions(settings){try{const data=await api('radarr/options');const root=document.getElementById('radarr_root_folder_path');const profile=document.getElementById('radarr_quality_profile_id');root.innerHTML='<option value="">Automatic</option>'+data.root_folders.map(item=>`<option value="${esc(item.path)}">${esc(item.path)}</option>`).join('');profile.innerHTML='<option value="0">Automatic</option>'+data.quality_profiles.map(item=>`<option value="${item.id}">${esc(item.name)}</option>`).join('');root.value=settings.root_folder_path||'';profile.value=String(settings.quality_profile_id||0);}catch(error){/* Radarr may not be configured yet. */}}
    async function loadDownloadWorkflow(){const badge=document.getElementById('workflow-status');const checks=document.getElementById('workflow-checks');try{const data=await api('setup/download-workflow');badge.textContent=({healthy:'Healthy',warning:'Review',error:'Unsafe',not_configured:'Needs details',unavailable:'Unavailable'})[data.status]||'Unavailable';badge.className=`badge ${esc(data.status)}`;checks.innerHTML=data.checks?.length?data.checks.map(check=>`<div class="workflow-check ${esc(check.level)}">${esc(check.message)}</div>`).join(''):`<div class="hint">${esc(data.message||'No workflow diagnostics are available.')}</div>`;}catch(error){badge.textContent='Unavailable';badge.className='badge error';checks.innerHTML=`<div class="workflow-check error">${esc(error.message)}</div>`;}}
    async function loadSetup(){setSetupMessage('Discovering apps and testing connections...');try{const data=await api('setup');serviceNames.forEach(name=>{const card=document.querySelector(`[data-service="${name}"]`);const connection=data.connections.services.find(item=>item.name===name)||{};const badge=card.querySelector('[data-status]');badge.textContent=statusLabel(connection.status);badge.className=`badge ${connection.status==='connected'?'connected':''}`;let detail=card.querySelector('[data-status-detail]');if(!detail){detail=document.createElement('div');detail.className='hint hidden';detail.dataset.statusDetail='';detail.setAttribute('role','status');card.querySelector('.fields').appendChild(detail);}detail.textContent=connection.message||'';detail.classList.toggle('hidden',!connection.message);const settings=data.settings[name]||{};if(name!=='tmdb'){const url=document.getElementById(`${name}_url`);if(!url.value)url.value=settings.url||data.discovery.services.find(item=>item.name===name)?.suggested_url||'';}if(name==='qbittorrent'){document.getElementById('qbittorrent_auth_method').value=settings.auth_method||'password';if(!document.getElementById('qbittorrent_username').value)document.getElementById('qbittorrent_username').value=settings.username||'';if(settings.api_key_set)document.getElementById('qbittorrent_api_key').placeholder='Saved, enter a new value to replace';if(settings.password_set)document.getElementById('qbittorrent_password').placeholder='Saved, enter a new value to replace';}else{const id=name==='tmdb'?'tmdb_api_key':`${name}_api_key`;if(settings.api_key_set)document.getElementById(id).placeholder='Saved, enter a new value to replace';}});await Promise.all([loadRadarrOptions(data.settings.radarr||{}),loadDownloadWorkflow()]);setSetupMessage(`${data.connections.connected} of 5 services connected.`);}catch(error){setSetupMessage(error.message,'error');}}
    document.getElementById('discover').addEventListener('click',loadSetup);document.getElementById('setup-form').addEventListener('submit',async event=>{event.preventDefault();const button=document.getElementById('save-setup');button.disabled=true;setSetupMessage('Saving and testing connections...');const updates={};['prowlarr_url','radarr_url','radarr_root_folder_path','radarr_quality_profile_id','sonarr_url','qbittorrent_url','qbittorrent_auth_method','qbittorrent_username'].forEach(id=>updates[id]=document.getElementById(id).value);secretFields.forEach(id=>{const value=document.getElementById(id).value;if(value)updates[id]=value;});try{await api('setup/integrations',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({updates,clear_secrets:[]})});secretFields.forEach(id=>document.getElementById(id).value='');setSetupMessage('Settings saved. Connections retested.','success');await loadSetup();await loadMovies();}catch(error){setSetupMessage(error.message,'error');}finally{button.disabled=false;}});

    async function loadUsers(){const container=document.getElementById('user-list');container.innerHTML='<div class="empty">Loading users...</div>';try{const users=await api('users');container.innerHTML=users.map(user=>`<article class="panel user-card" data-user-id="${esc(user.id)}"><div><h3>${esc(user.display_name)} <span class="account-source">${user.auth_source==='mediahub'?'MediaHub login':'Home Assistant'}</span></h3><div class="user-meta">${esc(user.username)} · ${user.active?'Active':'Disabled'} · Last seen ${esc(new Date(user.last_seen_at).toLocaleString())}</div><div class="stack hidden" data-reset-panel><label class="field">New password<input type="password" minlength="12" maxlength="1024" autocomplete="new-password" data-reset-password></label><button class="button primary" type="button" data-save-password>Save new password</button></div></div><div class="user-controls"><select data-role aria-label="Role"><option value="requester" ${user.role==='requester'?'selected':''}>Requester</option><option value="manager" ${user.role==='manager'?'selected':''}>Manager</option><option value="admin" ${user.role==='admin'?'selected':''}>Administrator</option></select>${user.auth_source==='mediahub'?'<button class="button" type="button" data-reset>Reset password</button>':''}<button class="button ${user.active?'danger':''}" type="button" data-active>${user.active?'Disable':'Enable'}</button></div></article>`).join('')||'<div class="empty">No users have been registered.</div>';container.querySelectorAll('[data-user-id]').forEach(card=>{const user=users.find(item=>item.id===card.dataset.userId);card.querySelector('[data-role]').addEventListener('change',async event=>{try{await api(`users/${encodeURIComponent(user.id)}/role`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({role:event.target.value})});toast(`${user.display_name}'s role was updated.`);await loadUsers();}catch(error){toast(error.message);await loadUsers();}});card.querySelector('[data-active]').addEventListener('click',async()=>{try{await api(`users/${encodeURIComponent(user.id)}/active`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({active:!user.active})});toast(`${user.display_name} was ${user.active?'disabled':'enabled'}.`);await loadUsers();}catch(error){toast(error.message);}});const reset=card.querySelector('[data-reset]');if(reset)reset.addEventListener('click',()=>card.querySelector('[data-reset-panel]').classList.toggle('hidden'));const save=card.querySelector('[data-save-password]');if(save)save.addEventListener('click',async()=>{const input=card.querySelector('[data-reset-password]');if(input.value.length<12){toast('Password must contain at least 12 characters.');return;}save.disabled=true;try{await api(`users/${encodeURIComponent(user.id)}/password`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({password:input.value})});input.value='';card.querySelector('[data-reset-panel]').classList.add('hidden');toast(`${user.display_name}'s password was reset and existing sessions were signed out.`);}catch(error){toast(error.message);}finally{save.disabled=false;}});});}catch(error){container.innerHTML=`<div class="empty">${esc(error.message)}</div>`;}}
    document.getElementById('refresh-users').addEventListener('click',loadUsers);
    document.getElementById('create-user-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget;const button=form.querySelector('button[type="submit"],button:not([type])');button.disabled=true;const message=document.getElementById('user-message');message.textContent='Creating account...';try{await api('users',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({display_name:document.getElementById('new-display-name').value,username:document.getElementById('new-username').value,password:document.getElementById('new-password').value,role:document.getElementById('new-role').value})});form.reset();message.textContent='Account created. Give the username and password to the user privately.';message.className='message success';await loadUsers();}catch(error){message.textContent=error.message;message.className='message error';}finally{button.disabled=false;}});

    function applyUser(user){state.user=user;document.getElementById('user').textContent=`${user.display_name} · ${user.role}`;const admin=user.role==='admin';document.getElementById('setup-nav').classList.toggle('hidden',!admin);document.getElementById('users-nav').classList.toggle('hidden',!admin);document.getElementById('logout').classList.toggle('hidden',user.auth_source!=='mediahub');document.getElementById('login-screen').classList.add('hidden');}
    function showLogin(message=''){state.user=null;document.getElementById('login-message').textContent=message;document.getElementById('login-password').value='';document.getElementById('login-screen').classList.remove('hidden');setTimeout(()=>document.getElementById('login-username').focus(),0);}
    document.getElementById('login-form').addEventListener('submit',async event=>{event.preventDefault();const button=document.getElementById('login-button');const message=document.getElementById('login-message');button.disabled=true;message.textContent='Signing in...';try{const response=await fetch(endpoint('auth/login'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:document.getElementById('login-username').value,password:document.getElementById('login-password').value})});const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(typeof body.detail==='string'?body.detail:'Sign in failed');applyUser(body);message.textContent='';showView('browse');await Promise.all([loadGenres(),loadMovies()]);}catch(error){message.textContent=error.message;}finally{button.disabled=false;}});
    document.getElementById('logout').addEventListener('click',async()=>{try{await api('auth/logout',{method:'POST'});}catch(error){/* Clear the local screen even if the server session already expired. */}showLogin('You have been signed out.');});

    async function initialise(){try{const user=await api('users/me');applyUser(user);await Promise.all([loadGenres(),loadMovies()]);}catch(error){if(error.status===401){showLogin();return;}document.getElementById('movies').innerHTML=`<div class="empty">${esc(error.message)}</div>`;}}
    initialise();
  </script>
</body>
</html>
"""
